-- Seventh batch of explicitly labelled supplemental study outlines for MBH histology.
-- Idempotent: existing answers are never overwritten.
with supplemental_answers(id, answer) as (
  values
  ('859b4caf-de6b-5c77-8406-080f7ef2e48d', 'Учебный конспект MEDBIOHIM (дополнение; сверьте с лекцией). Эндокринные железы не имеют выводных протоков и выделяют гормоны в кровь или тканевую жидкость; обычно они богато васкуляризированы и содержат фенестрированные капилляры. Клетки располагаются тяжами, группами или фолликулами (пример — щитовидная железа). Гормональная секреция регулируется нервными сигналами, обратной связью, рилизинг-факторами и концентрацией веществ в крови. В отличие от экзокринных желез, секрет не проходит по протоку к поверхности.'),
  ('c0488c3a-e6b1-5d31-aa00-d32ad6a82a3b', 'Учебный конспект MEDBIOHIM (дополнение; сверьте с лекцией). Аденогипофиз содержит соматотропы, лактотропы, тиротропы, кортикотропы и гонадотропы; они выделяют соответствующие гормоны и регулируются гипоталамическими рилизинг- и ингибирующими факторами. Нейрогипофиз хранит и выделяет вазопрессин и окситоцин, синтезируемые в гипоталамусе. Кровоснабжение включает гипоталамо-гипофизарную портальную систему, которая доставляет регулирующие факторы к аденогипофизу; капилляры фенестрированные, что облегчает обмен гормонов.'),
  ('694986ac-39d0-569b-abc0-bb5d53579b52', 'Учебный конспект MEDBIOHIM (дополнение; сверьте с лекцией). Гипофиз имеет двойное происхождение: аденогипофиз развивается из эктодермального кармана Ратке, нейрогипофиз — из нейроэктодермы промежуточного мозга. Аденогипофиз включает pars distalis, pars intermedia и pars tuberalis; в pars distalis различают ацидофильные, базофильные и хромофобные клетки. Нейрогипофиз содержит аксоны гипоталамических нейронов, окончания с нейросекретом и питуициты. Связь с гипоталамусом осуществляется портальной сосудистой системой и аксонами, доставляющими вазопрессин и окситоцин.'),
  ('9edfac54-0d51-5322-adbb-8c284673a2e6', 'Учебный конспект MEDBIOHIM (дополнение; сверьте с лекцией). Кора больших полушарий развивается из телэнцефалической нейроэктодермы и имеет шестислойную организацию неокортекса: молекулярный, наружный зернистый, наружный пирамидный, внутренний зернистый, внутренний пирамидный и полиморфный слои. Цитоархитектоника описывает распределение нейронов, миелоархитектоника — ход и плотность миелиновых волокон. Вертикальные функциональные колонки объединяют нейроны, обрабатывающие сходные входы. Между областями коры различается выраженность слоёв в зависимости от функции.'),
  ('ce1a2a2b-a4f5-54d4-a946-ada551130585', 'Учебный конспект MEDBIOHIM (дополнение; сверьте с лекцией). Губа имеет кожную, промежуточную (красную кайму) и слизистую части. Кожная часть покрыта ороговевающим эпителием с волосами и кожными железами; красная кайма имеет тонкий эпителий и высокие сосочковые капилляры, поэтому выглядит красной; слизистая часть покрыта многослойным плоским неороговевающим эпителием. В подслизистой расположены малые губные слюнные железы, преимущественно слизистые/смешанные. В основе губы находятся пучки поперечно-полосатой скелетной мышцы.'),
  ('e9ed20b0-f857-5f64-98d4-d4abf15ce4e9', 'Учебный конспект MEDBIOHIM (дополнение; сверьте с лекцией). Развитие зуба проходит стадии зубной пластинки, почки, шапочки и колокольчика. Эмалевый орган формирует амелобласты и эмаль; зубной сосочек даёт начало одонтобластам, дентину и пульпе; зубной мешочек формирует цемент, периодонт и часть альвеолярной кости. Молочные и постоянные зубы развиваются по сходному плану, но постоянные зубы формируются из преемников зубной пластинки. Дифференцировка эпителиальных и мезенхимных клеток координируется взаимными сигнальными взаимодействиями.'),
  ('38d874c5-62ce-50ae-a62e-0be1d07d6e35', 'Учебный конспект MEDBIOHIM (дополнение; сверьте с лекцией). Зуб включает эмаль, дентин, цемент и пульпу. Эмаль почти полностью минерализована и образуется амелобластами до прорезывания; дентин формируется одонтобластами и содержит канальцы; цемент покрывает корень и служит местом прикрепления периодонтальных волокон; пульпа — сосудисто-нервная рыхлая соединительная ткань. Питание эмали после прорезывания ограничено, дентин и пульпа поддерживают связь через одонтобласты. Регенерация эмали отсутствует, образование вторичного и третичного дентина возможно; с возрастом полость пульпы уменьшается.'),
  ('82cdcd6f-5d58-5bcf-805c-4fbdda44e7b7', 'Учебный конспект MEDBIOHIM (дополнение; сверьте с лекцией). Вопрос объединяет две темы, поэтому готовьтесь отдельно. Дыхательные пути проводят, согревают, увлажняют и очищают воздух; трахея содержит реснитчатый многорядный эпителий, железы и хрящевые кольца, бронхи — хрящевые пластинки и развитую гладкую мышцу. Кожа включает эпидермис (многослойный плоский ороговевающий эпителий) и дерму из соединительной ткани; функции — барьер, терморегуляция, чувствительность и защита от потери воды.'),
  ('43453d32-b814-5ce9-a10e-93ae20ff258f', 'Учебный конспект MEDBIOHIM (дополнение; сверьте с лекцией). Зуб состоит из коронки, шейки и корня. Основные ткани: эмаль покрывает коронку, дентин составляет основную массу, цемент покрывает корень, пульпа содержит сосуды, нервы и рыхлую соединительную ткань. Периодонтальная связка соединяет цемент с альвеолярной костью, а десна формирует мягкотканный барьер. Функции зуба связаны с механической обработкой пищи; в гистологическом ответе важно различать высокоминерализованную эмаль, канальцевый дентин и клеточную пульпу.'),
  ('c3df3053-148a-5d70-88f8-c6a1c25ca005', 'Учебный конспект MEDBIOHIM (дополнение; сверьте с лекцией). Десна покрыта многослойным плоским эпителием; различают наружный оральный эпителий, бороздковый эпителий и эпителий прикрепления. Десневая борозда — узкое пространство между зубом и свободной десной; её эпителий обычно менее ороговевающий. Эпителий прикрепления образует специализированный контакт с поверхностью зуба и обеспечивает барьер, хотя он более проницаем для миграции лейкоцитов. Собственная пластинка содержит плотные коллагеновые пучки, сосуды и нервные окончания.'),
  ('7e7d21e6-819d-577f-a18a-4d93b6a39880', 'Учебный конспект MEDBIOHIM (дополнение; сверьте с лекцией). Дентин — минерализованная ткань, содержащая преимущественно гидроксиапатит и органический матрикс, главным образом коллаген I типа. Дентинные канальцы проходят от пульпы к периферии и содержат отростки одонтобластов и дентинную жидкость; плотность и направление канальцев меняются по глубине. Минерализация идёт фронтом от предентина; перитубулярный дентин более минерализован, чем интертубулярный. Дентин живой и чувствительный благодаря связи с одонтобластами и нервными структурами пульпы.'),
  ('5b6442d4-c56a-5562-b97d-97604a9c0aeb', 'Учебный конспект MEDBIOHIM (дополнение; сверьте с лекцией). Плащевой дентин располагается периферически и содержит относительно более крупные коллагеновые волокна; околопульпарный дентин составляет основную массу дентина. Предентин — неминерализованный слой матрикса у пульпы, который постепенно минерализуется. Первичный дентин формируется при развитии зуба, вторичный медленно откладывается после прорезывания, третичный образуется локально в ответ на раздражение или повреждение. Одонтобласты сохраняют отростки в дентинных канальцах и участвуют в защитной реакции.'),
  ('fcb3ce48-dbb6-58ae-aabd-f06e2f9c46b3', 'Учебный конспект MEDBIOHIM (дополнение; сверьте с лекцией). Чувствительная иннервация лица и зубочелюстной области в основном связана с тройничным нервом. Тройничный узел содержит тела псевдоуниполярных чувствительных нейронов; периферические отростки идут к рецепторам, центральные — в ствол мозга. Нижнечелюстной нерв (V3) — смешанная ветвь, несёт чувствительные волокна от нижних зубов, десны и слизистой, а также двигательные волокна к жевательным мышцам. Пульпа зуба богато иннервирована чувствительными волокнами, что объясняет выраженную болевую чувствительность.'),
  ('f2eee4a5-02a4-5ff5-ad11-fe278904e0ea', 'Учебный конспект MEDBIOHIM (дополнение; сверьте с лекцией). Капилляры — сосуды обмена, стенка которых образована эндотелием, базальной мембраной и иногда перицитами. Непрерывные капилляры имеют сплошной эндотелий (мышцы, ЦНС — с особенностями барьера); фенестрированные — поры для усиленного обмена (эндокринные железы, кишечник, почка); синусоидные имеют широкие просветы и прерывистую стенку (печень, селезёнка, костный мозг). Обмен зависит от давления, проницаемости и площади поверхности. Гистогематический барьер ограничивает переход веществ между кровью и тканью.'),
  ('87111aad-5f66-5d34-9ca8-ba2cf9f12d6a', 'Учебный конспект MEDBIOHIM (дополнение; сверьте с лекцией). Желудок развивается из энтодермальной кишки; мышечная и соединительная ткани происходят из мезодермы. Стенка включает слизистую, подслизистую, мышечную оболочку и серозу. В области дна и тела желудочные железы содержат париетальные клетки (HCl и внутренний фактор), главные клетки (пепсиноген), слизистые клетки и эндокринные клетки; в пилорическом отделе больше слизистых и G-клеток. Эпителий обновляется стволовыми клетками перешейка желез; сосуды и автономная иннервация регулируют секрецию и моторику.'),
  ('859e3e91-ab3b-50a4-9cd0-ab9be623186d', 'Учебный конспект MEDBIOHIM (дополнение; сверьте с лекцией). Артерии делят на эластические (аорта и крупные ветви), мышечные (распределительные) и переходные. Стенка состоит из интимы, медии и адвентиции. В аорте медия особенно толстая и содержит многочисленные эластические мембраны, между которыми располагаются гладкие миоциты; это позволяет растягиваться при систоле и поддерживать диастолический кровоток. Интима включает эндотелий и подлежащую соединительную ткань; адвентиция содержит сосуды сосудов и нервные волокна.'),
  ('9947865f-6d41-5c0d-967d-91d4d9def90a', 'Учебный конспект MEDBIOHIM (дополнение; сверьте с лекцией). Эпителий воздухоносных путей в основном происходит из энтодермы передней кишки, а хрящ, гладкая мышца и соединительная ткань — из окружающей мезодермы. Трахея имеет многорядный реснитчатый эпителий, железистую подслизистую, гиалиновые хрящевые кольца и заднюю мышечную стенку. В бронхах хрящ представлен пластинками, гладкая мышца выражена, а эпителий становится ниже по мере уменьшения калибра. Мукоцилиарный клиренс удаляет частицы и микроорганизмы.'),
  ('f5a66665-4651-5119-9320-e447815867ef', 'Учебный конспект MEDBIOHIM (дополнение; сверьте с лекцией). Слизистая желудка образует ямки и трубчатые железы; однослойный цилиндрический поверхностный эпителий выделяет защитную слизь и бикарбонат. В теле и дне железы париетальные клетки выделяют соляную кислоту и внутренний фактор, главные — пепсиноген, слизистые клетки — слизь; эндокринные клетки регулируют секрецию. В пилорическом отделе ямки глубже и преобладают слизистые железы. Эпителий быстро обновляется благодаря стволовым клеткам; моторика и секреция регулируются нервными и гормональными механизмами.'),
  ('e4525407-fa4f-528a-8f93-a04feec2cfbd', 'Учебный конспект MEDBIOHIM (дополнение; сверьте с лекцией). При развитии костной альвеолы прямой остеогенез происходит из мезенхимы: клетки-предшественники дифференцируются в остеобласты, которые синтезируют остеоид и обеспечивают минерализацию. Формируются костные трабекулы и пластинки, затем компактные участки альвеолярной кости; ремоделирование продолжается в ответ на нагрузку и перемещение зуба. Периодонтальная связка передаёт механические сигналы и участвует в согласованной резорбции и образовании кости.'),
  ('279846c3-6e6e-5543-9223-e055157bb162', 'Учебный конспект MEDBIOHIM (дополнение; сверьте с лекцией). Десна относится к жевательной слизистой; эпителий обычно многослойный плоский ороговевающий или паракератинизированный. Собственная пластинка соединительной ткани имеет сосочковый и более глубокий сетчатый слои, богата коллагеновыми волокнами и сосудами; подслизистая в прикреплённой десне выражена слабо или отсутствует. Рецепторные окончания обеспечивают чувствительность к давлению и боли. Десневой эпителий формирует барьер вокруг зуба и соединяется с поверхностью зуба в области зубодесневого прикрепления.')
)
update public.exam_questions q
set answer = s.answer, updated_at = now()
from supplemental_answers s
where q.id = s.id::uuid
  and q.subject_slug = 'histology'
  and nullif(btrim(q.answer), '') is null;
